// A registered application page: all actions are coding-owned tools.
const state = (path: string) => ({ $state: path });
const bind = (path: string) => ({ $bindState: path });
const node = (type: string, props: Record<string, unknown>, children: string[] = []) => ({ type, props, children });
const action = (label: string, operation: string, args: Record<string, unknown>, extra: Record<string, unknown> = {}) => ({
  ...node("Button", { label, ...extra }), on: { press: { action: "call", params: { tool: "ui-command", args: { action: operation, "request-key": state("/catalog/requestKey"), ...args }, result: "/detail" } } },
});
export const PAGE = {
  id: "main", title: "编码工作台",
  data: {
    catalog: { tool: "ui-catalog" },
    detail: { tool: "ui-work", args: { "work-id": state("/detail/workId") }, refresh: 5 },
  },
  spec: { root: "root", state: { form: { project: "", goal: "", workId: "", message: "", question: "", answer: "", result: "" } }, elements: {
    root: node("Stack", { gap: "lg" }, ["intro", "columns"]),
    intro: node("Text", { text: "选择项目、描述目标，然后查看编码进度。页面每 5 秒更新当前工作；接受成果不会提交或合并代码。", variant: "muted" }),
    columns: node("Grid", { columns: 2, gap: "lg" }, ["sidebar", "main"]),
    sidebar: node("Stack", { gap: "lg" }, ["new", "history"]),
    new: node("Card", { title: "新建工作" }, ["notice", "project", "goal", "create"]),
    notice: node("Text", { text: state("/catalog/notice"), variant: "muted" }),
    project: node("Select", { label: "服务器项目", name: "project", placeholder: "选择已授权项目", options: state("/catalog/projects"), value: bind("/form/project") }),
    goal: node("Textarea", { label: "工作目标", name: "goal", placeholder: "例如：修复登录页的问题，并运行相关检查", value: bind("/form/goal") }),
    create: action("开始工作", "create", { project: state("/form/project"), text: state("/form/goal") }, { disabled: { $cond: { $state: "/catalog/configured", eq: false }, $then: true, $else: false } }),
    history: node("Card", { title: "已有工作" }, ["workSelect", "open", "refresh", "empty", "workList"]),
    workSelect: node("Select", { label: "选择工作", name: "work", placeholder: "选择一项工作", options: state("/catalog/workIds"), value: bind("/form/workId") }),
    open: { ...node("Button", { label: "打开工作", variant: "secondary" }), on: { press: { action: "call", params: { tool: "ui-work", args: { "work-id": state("/form/workId") }, result: "/detail", reload: false } } } },
    refresh: { ...node("Button", { label: "刷新工作列表", variant: "secondary" }), on: { press: { action: "call", params: { tool: "ui-catalog", result: "/catalog", reload: false } } } },
    empty: { ...node("Text", { text: "还没有服务器编码工作。填写上方目标即可开始。", variant: "muted" }), visible: { $state: "/catalog/hasWorks", eq: false } },
    workList: { ...node("Stack", { gap: "sm" }, ["workGoal", "workId", "workStatus"]), repeat: { statePath: "/catalog/works", key: "id" } },
    workGoal: node("Text", { text: { $item: "goal" } }),
    workId: node("Text", { text: { $item: "id" }, variant: "muted" }),
    workStatus: node("Badge", { text: { $item: "status" }, variant: "secondary" }),
    main: node("Stack", { gap: "lg" }, ["choose", "detail"]),
    choose: { ...node("Card", { title: "工作详情" }, ["chooseHelp"]), visible: { $state: "/detail/workId", not: true } },
    chooseHelp: node("Text", { text: "新建工作，或从左侧打开已有工作。手机上请从上方选择。", variant: "muted" }),
    detail: { ...node("Stack", { gap: "lg" }, ["summary", "conversation", "questions", "progress", "results"]), visible: { $state: "/detail/workId" } },
    summary: node("Card", { title: "当前工作" }, ["detailGoal", "detailId", "detailStatus", "stopText", "stop"]),
    detailGoal: node("Heading", { text: state("/detail/goal"), level: "h3" }),
    detailId: node("Text", { text: state("/detail/workId"), variant: "muted" }),
    detailStatus: node("Badge", { text: state("/detail/status") }),
    stopText: node("Text", { text: state("/detail/stop"), variant: "muted" }),
    stop: { ...action("请求停止", "stop", { "work-id": state("/detail/workId") }, { variant: "danger" }), visible: { $state: "/detail/canStop", eq: true } },
    conversation: node("Card", { title: "回复与补充要求" }, ["output", "supplement", "send"]),
    output: node("Markdown", { content: state("/detail/output") }),
    supplement: { ...node("Textarea", { label: "补充要求", name: "message", value: bind("/form/message") }), visible: { $state: "/detail/canSend", eq: true } },
    send: { ...action("发送补充要求", "send", { "work-id": state("/detail/workId"), text: state("/form/message") }), visible: { $state: "/detail/canSend", eq: true } },
    questions: node("Card", { title: "需要你的答复" }, ["noQuestions", "questionList", "questionSelect", "answerText", "answer"]),
    noQuestions: { ...node("Text", { text: "当前没有等待答复的问题。", variant: "muted" }), visible: { $state: "/detail/hasQuestions", eq: false } },
    questionList: { ...node("Stack", { gap: "sm" }, ["questionTitle", "questionHelp"]), repeat: { statePath: "/detail/questions", key: "id" } },
    questionTitle: node("Text", { text: { $item: "title" } }), questionHelp: node("Text", { text: { $item: "help" }, variant: "muted" }),
    questionSelect: { ...node("Select", { label: "选择问题", name: "question", placeholder: "选择待答复问题", options: state("/detail/questionIds"), value: bind("/form/question") }), visible: { $state: "/detail/hasQuestions", eq: true } },
    answerText: { ...node("Textarea", { label: "答复", name: "answer", value: bind("/form/answer") }), visible: { $state: "/detail/hasQuestions", eq: true } },
    answer: { ...action("提交答复", "answer", { "work-id": state("/detail/workId"), question: state("/form/question"), text: state("/form/answer") }), visible: { $state: "/detail/hasQuestions", eq: true } },
    progress: node("Collapsible", { title: "执行进度（最多 100 条）", defaultOpen: true }, ["limited", "events"]),
    limited: { ...node("Text", { text: "部分历史进度已过期或省略，请结合最终回复和成果核对。", variant: "muted" }), visible: { $state: "/detail/limited", eq: true } },
    events: { ...node("Stack", { gap: "sm" }, ["eventText"]), repeat: { statePath: "/detail/progress", key: "sequence" } },
    eventText: node("CollapsedText", { content: { $item: "text" }, limit: 200 }),
    results: node("Card", { title: "成果验收" }, ["resultHelp", "patch", "resultList", "resultSelect", "accept"]),
    patch: node("Collapsible", { title: "最新成果的代码差异", defaultOpen: false }, ["patchText"]),
    patchText: node("Preformatted", { text: state("/detail/patch") }),
    resultHelp: node("Text", { text: "执行停止后生成成果版本。接受只记录验收，不会提交、合并或删除项目文件。", variant: "muted" }),
    resultList: { ...node("Stack", { gap: "sm" }, ["resultId", "resultRef", "resultStatus"]), repeat: { statePath: "/detail/results", key: "id" } },
    resultId: node("Text", { text: { $item: "id" } }), resultRef: node("Text", { text: { $item: "ref" }, variant: "muted" }), resultStatus: node("Badge", { text: { $item: "status" }, variant: "secondary" }),
    resultSelect: node("Select", { label: "待验收版本", name: "result", placeholder: "选择已核对的成果", options: state("/detail/resultIds"), value: bind("/form/result") }),
    accept: action("接受所选成果", "accept", { "work-id": state("/detail/workId"), result: state("/form/result") }),
  } },
};
